import { redirect } from "next/navigation";

export const dynamic = "force-dynamic";

export default function OrderPage() {
  redirect("/dashboard/deploy");
}

"use client";

import { useCallback, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { EmptyState } from "@/components/ui/primitives";
import { DeployWizard } from "@/components/customer/DeployWizard";
import { HostingDeployWizard } from "@/components/customer/HostingDeployWizard";
import { GameDeployWizard } from "@/components/customer/GameDeployWizard";
import { EmailHosting } from "@/components/customer/EmailHosting";

/* Props for each wizard are taken verbatim from the components themselves, so the
   hub can never drift from what a wizard actually expects. The deploy page computes
   these identically to how each product's old page did — this component only relays
   them. None of the checkout / charge / first-month-free logic lives here. */
type VpsProps = React.ComponentProps<typeof DeployWizard>;
type HostingProps = React.ComponentProps<typeof HostingDeployWizard>;
type GameProps = React.ComponentProps<typeof GameDeployWizard>;
type EmailProps = React.ComponentProps<typeof EmailHosting>;

export type DeployProduct = "vps" | "hosting" | "game" | "email";

const PRODUCTS: DeployProduct[] = ["vps", "hosting", "game", "email"];

function isProduct(v: string | null): v is DeployProduct {
  return v === "vps" || v === "hosting" || v === "game" || v === "email";
}

/* ── Per-product in-theme accent. Every class is a LITERAL so Tailwind's JIT keeps
      it. Our palette only: violet (brand) · cyan · emerald · blue. ─────────────── */
type Accent = {
  label: string;
  desc: string;
  badge?: { text: string; cls: string };
  /** Gradient for the rounded icon tile. */
  tile: string;
  /** Glow shadow behind the icon tile. */
  tileGlow: string;
  /** Border + ring the ACTIVE card gets, in the product's own accent. */
  activeCard: string;
  /** Accent text (arrow + active title tint). */
  text: string;
  Icon: (p: { className?: string }) => React.ReactElement;
};

const ACCENTS: Record<DeployProduct, Accent> = {
  vps: {
    label: "VPS Hosting",
    desc: "Blazing-fast NVMe VPS with full root access and complete control.",
    badge: { text: "Most Popular", cls: "border-brand-400/40 bg-brand-500/15 text-brand-200" },
    tile: "from-brand-500 to-brand-700",
    tileGlow: "shadow-[0_0_28px_-6px_rgb(111_71_245_/_0.65)]",
    activeCard: "border-brand-400/60 ring-1 ring-brand-500/40 shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.5)]",
    text: "text-brand-300",
    Icon: ({ className }) => (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <rect x="3" y="4" width="18" height="7" rx="1.5" />
        <rect x="3" y="13" width="18" height="7" rx="1.5" />
        <path d="M7 7.5h.01M7 16.5h.01" />
      </svg>
    ),
  },
  hosting: {
    label: "Shared Hosting",
    desc: "One-click WordPress & sites. Fast, secure, easy to manage.",
    tile: "from-accent-cyan to-accent-blue",
    tileGlow: "shadow-[0_0_28px_-6px_rgb(34_211_238_/_0.6)]",
    activeCard: "border-accent-cyan/60 ring-1 ring-accent-cyan/40 shadow-[0_0_40px_-10px_rgb(34_211_238_/_0.5)]",
    text: "text-accent-cyan",
    Icon: ({ className }) => (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <circle cx="12" cy="12" r="9" />
        <path d="M3 12h18M12 3c2.5 2.4 3.8 5.6 3.8 9S14.5 18.6 12 21c-2.5-2.4-3.8-5.6-3.8-9S9.5 5.4 12 3Z" />
      </svg>
    ),
  },
  game: {
    label: "Game Servers",
    desc: "Instantly deploy Minecraft, Rust, Valheim, Palworld & more.",
    tile: "from-emerald-400 to-emerald-600",
    tileGlow: "shadow-[0_0_28px_-6px_rgb(16_185_129_/_0.6)]",
    activeCard: "border-emerald-400/60 ring-1 ring-emerald-500/40 shadow-[0_0_40px_-10px_rgb(16_185_129_/_0.5)]",
    text: "text-emerald-300",
    Icon: ({ className }) => (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <path d="M6 11h4M8 9v4" />
        <path d="M15.5 10.5h.01M18 12.5h.01" />
        <rect x="2.5" y="6.5" width="19" height="11" rx="5.5" />
      </svg>
    ),
  },
  email: {
    label: "Business Email",
    desc: "Professional email with your domain. Secure, private, ad-free.",
    badge: { text: "NEW", cls: "border-accent-blue/40 bg-accent-blue/15 text-blue-200" },
    tile: "from-accent-blue to-blue-600",
    tileGlow: "shadow-[0_0_28px_-6px_rgb(59_130_246_/_0.6)]",
    activeCard: "border-accent-blue/60 ring-1 ring-accent-blue/40 shadow-[0_0_40px_-10px_rgb(59_130_246_/_0.5)]",
    text: "text-blue-300",
    Icon: ({ className }) => (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <rect x="3" y="5" width="18" height="14" rx="2" />
        <path d="m3.5 7 8.5 6 8.5-6" />
      </svg>
    ),
  },
};

/* ── Isometric server-stack hero illustration. Pure SVG so it themes cleanly and
      needs no asset. Three stacked blades on an iso base with glowing brand edges,
      status LEDs and a soft ground glow — reads clearly as a server. To swap in a
      real render later, replace this element with <img src="…" /> — nothing else
      depends on it. */
function ServerRackArt({ className }: { className?: string }) {
  // Three stacked iso blades; each is a top face + front face + side face.
  const blades = [0, 1, 2];
  return (
    <svg viewBox="0 0 320 300" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden>
      <defs>
        <linearGradient id="hubTop" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#1b2646" />
          <stop offset="1" stopColor="#121a34" />
        </linearGradient>
        <linearGradient id="hubFront" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#131c38" />
          <stop offset="1" stopColor="#0b1226" />
        </linearGradient>
        <linearGradient id="hubSide" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#0d1428" />
          <stop offset="1" stopColor="#080d1c" />
        </linearGradient>
        <linearGradient id="hubEdge" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#8a70fb" />
          <stop offset="1" stopColor="#22d3ee" />
        </linearGradient>
        <radialGradient id="hubGlow" cx="0.5" cy="0.5" r="0.5">
          <stop offset="0" stopColor="#6f47f5" stopOpacity="0.55" />
          <stop offset="1" stopColor="#6f47f5" stopOpacity="0" />
        </radialGradient>
      </defs>

      {/* ground glow */}
      <ellipse cx="160" cy="256" rx="120" ry="30" fill="url(#hubGlow)" />

      {blades.map((b) => {
        // iso projection: each blade sits 46px higher than the last.
        const oy = 190 - b * 46;
        const dx = 120; // half-width along the iso X
        const dz = 60; // depth along iso Y
        const h = 26; // blade thickness (front face)
        const cx = 160;
        // key points of the top rhombus
        const top = `${cx},${oy - dz / 2} ${cx + dx},${oy} ${cx},${oy + dz / 2} ${cx - dx},${oy}`;
        const led = b === 1 ? "#22d3ee" : "#8a70fb";
        return (
          <g key={b}>
            {/* top face */}
            <polygon points={top} fill="url(#hubTop)" stroke="url(#hubEdge)" strokeWidth="1.25" strokeOpacity="0.6" />
            {/* front-left face */}
            <polygon
              points={`${cx - dx},${oy} ${cx},${oy + dz / 2} ${cx},${oy + dz / 2 + h} ${cx - dx},${oy + h}`}
              fill="url(#hubFront)"
            />
            {/* front-right face */}
            <polygon
              points={`${cx},${oy + dz / 2} ${cx + dx},${oy} ${cx + dx},${oy + h} ${cx},${oy + dz / 2 + h}`}
              fill="url(#hubSide)"
            />
            {/* glowing seam along the front bottom edge */}
            <polyline
              points={`${cx - dx},${oy + h} ${cx},${oy + dz / 2 + h} ${cx + dx},${oy + h}`}
              stroke="url(#hubEdge)"
              strokeWidth="1.5"
              strokeOpacity="0.85"
              fill="none"
            />
            {/* drive slots on the left face */}
            {[0, 1, 2].map((s) => (
              <line
                key={s}
                x1={cx - dx + 16 + s * 30}
                y1={oy + 12 + (16 + s * 30) * (dz / 2 / dx)}
                x2={cx - dx + 30 + s * 30}
                y2={oy + 12 + (30 + s * 30) * (dz / 2 / dx)}
                stroke="#2b3a63"
                strokeWidth="3"
                strokeLinecap="round"
              />
            ))}
            {/* status LEDs on the right face */}
            <circle cx={cx + dx - 16} cy={oy + 13} r="3.2" fill={led}>
              <animate attributeName="opacity" values="0.4;1;0.4" dur={`${2 + b * 0.5}s`} repeatCount="indefinite" />
            </circle>
            <circle cx={cx + dx - 16} cy={oy + 21} r="3.2" fill="#22d3ee" opacity="0.5" />
          </g>
        );
      })}
    </svg>
  );
}

export function DeployHub({
  vps,
  hosting,
  game,
  email,
  hostingPromoOn = false,
}: {
  /** null when no active plans/images are configured (VPS deploy unavailable). */
  vps: VpsProps | null;
  hosting: HostingProps;
  /** null when no game families have active tiers. */
  game: GameProps | null;
  email: EmailProps;
  /** The first-month-free promo is RUNNING (offer exists) — drives the marketing
   *  "1st month free" badge on the Shared Hosting tab. The actual $0-vs-full price
   *  at checkout stays gated per-account/IP (hosting.firstMonthFree). */
  hostingPromoOn?: boolean;
}) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const initial = searchParams.get("product");
  const [active, setActive] = useState<DeployProduct>(isProduct(initial) ? initial : "vps");

  const select = useCallback(
    (p: DeployProduct) => {
      setActive(p);
      // Deep-link without a full navigation so the mounted wizard/state is preserved.
      const params = new URLSearchParams(Array.from(searchParams.entries()));
      params.set("product", p);
      router.replace(`/dashboard/deploy?${params.toString()}`, { scroll: false });
    },
    [router, searchParams]
  );

  const activeAccent = ACCENTS[active];

  const wizard = useMemo(() => {
    // Only the ACTIVE product's wizard is ever mounted.
