                    )}
                  </span>
                  <span className="mt-0.5 block text-xs leading-snug text-slate-400">{a.desc}</span>
                  <span className={`mt-1.5 inline-flex items-center gap-1 text-xs font-medium transition-transform group-hover:translate-x-0.5 ${a.text}`}>
                    {isActive ? "Selected" : "Choose"} <span aria-hidden>→</span>
