          })}
        </div>

      </section>

      {/* ── Active product's wizard ──────────────────────────────────────────── */}
      <div>
        {/* No repeated product-name heading here — the product card row above
            (and its "Selected" state) already identifies which wizard is active;
            a second label right above the step indicator was pure redundancy. */}
        {active === "email" && (
          <div className="mb-4 flex justify-end">
            <a
              href="/dashboard/email"
              className="inline-flex items-center gap-1 text-xs font-medium text-blue-300 hover:text-blue-200"
            >
              Manage your email subscriptions →
            </a>
          </div>
        )}
        {wizard}
      </div>
    </div>
  );
}

