async function reportPurchase(
  redirect: string,
  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
  email?: string,
  userId?: string,
  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
  prod?: string,
): Promise<string> {
  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
  const currency = (session.currency ?? "usd").toUpperCase();
  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
  // Wrapped so the webhook path (no browser request scope) simply sends without them.
  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
  try {
    const [ck, h] = await Promise.all([cookies(), headers()]);
    fbc = ck.get("_fbc")?.value || undefined;
    fbp = ck.get("_fbp")?.value || undefined;
    userAgent = h.get("user-agent") ?? undefined;
    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
  } catch {
    /* no request scope (webhook) — send without cookie/UA signals */
  }
  const { eventId } = await sendMetaConversion({
    eventName: "Purchase",
    email,
    value,
    currency,
    sourceUrl: redirect,
    fbc,
    fbp,
    userAgent,
    clientIp,
    externalId: userId,
  });
  // SERVER-SIDE Google Ads offline conversion for the paid order, using the captured
  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
  // AND a generic "purchase". Inert until the Ads API creds are configured.
  if (userId) {
    try {
      const { recordAdsConversion } = await import("./google-ads");
      const valueCents = Math.round(value * 100);
      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
    } catch {
      /* tracking is best-effort — the order is already fulfilled */
    }
  }
  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
}

