    server = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
