"use client";

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { RevealPassword, CopyText } from "@/components/customer/ServerAccess";

/**
 * The Hostinger-style "your order is being set up" interstitial — shown full
 * screen right after a customer pays/deploys, while the VM is still
 * PENDING/PROVISIONING, then a one-time success card once it flips to
 * RUNNING. Deliberately built as a pure overlay on TOP of the existing
 * server-detail page rather than a new route: the page underneath keeps
 * rendering (and keeps refreshing via the existing `<AutoRefresh />`) exactly
 * as it always has, so this component only ever needs to react to props that
 * are already being recomputed every 5s — no new polling loop, no new server
 * action.
 *
 * Visibility rules (see the effect below for the full state machine):
 *   - Shows the "provisioning" phase whenever the server is in a transitional
 *     status. Sets a sessionStorage flag so a REFRESH mid-provision still
 *     shows it (not just the initial mount).
 *   - Shows "success" the moment that flag is set AND the status flips to
 *     RUNNING — OR, for the case where the server was ALREADY done by the
 *     time this page first loaded (real orders provision in under two
 *     minutes, but this platform's SANDBOX mode completes instantly), when
 *     the URL carries the `purchase=1` marker `reportPurchase` already stamps
 *     onto every real paid-order redirect.
 *   - Never shown for a customer just casually revisiting an old, already-
 *     running server — that's the whole reason for the two gates above
 *     instead of "status === RUNNING".
 *   - Once dismissed, stays dismissed for this server (sessionStorage),
 *     surviving a refresh.
 */
export function ProvisioningOverlay({
  serverId,
  status,
  transitional,
  justPaid,
  provisionError,
  productLabel,
  hostname,
  connectAddress,
  planName,
  osName,
  rootPassword,
  rootPasswordLabel,
  extraInfo,
  readyStatus = "RUNNING",
  liveStep = null,
  liveStepActive = false,
  dashboardHref,
}: {
  serverId: string;
  status: string;
  transitional: boolean;
  /**
   * True only when THIS request's URL carried `?purchase=1` — read server-side
   * from `searchParams` and passed down as a plain prop, not re-derived from
   * `window.location.search` on the client. `app/dashboard/layout.tsx`'s
   * PurchaseTracker also reads `?purchase=1` (to fire the conversion pixel)
   * and then strips it via `router.replace()`; a client-side read here loses
   * that race unpredictably (confirmed in testing — a lazy `useState`
   * initializer still lost it under the App Router's RSC re-render on
   * navigation). The server captured the true value from the original
   * request before any client-side history mutation could touch it.
   */
  justPaid: boolean;
  provisionError?: string | null;
  /** "server" | "game server" | "hosting account" | etc — used in copy ("Your ... is live!"). */
  productLabel: string;
  hostname: string;
  /** The connect string to show, e.g. "ssh root@1.2.3.4" or "1.2.3.4:25565" — null while not yet assigned. */
  connectAddress: string | null;
  planName: string;
  osName: string | null;
  rootPassword: string | null;
  /** Label for the `rootPassword` row — defaults to "Root password" (VPS/game). Shared
   *  Hosting has no root password; pass "SFTP password" there instead of inventing a
   *  VPS-shaped field that doesn't exist for that product. */
  rootPasswordLabel?: string;
  /** Extra product-specific rows appended to the success card's info panel (e.g.
   *  Shared Hosting's "SFTP username" / "Website" — fields a VPS has no analogue
   *  for), rather than forcing every product into VPS-shaped fields. */
  extraInfo?: { label: string; value: string; href?: string }[];
  /** The status value that means "done, show the success card" — "RUNNING" for a
   *  VPS/game server, "ACTIVE" for a Shared Hosting account. */
  readyStatus?: string;
  /** Real (never fake/invented) current-step label, e.g. "Cloning your server…" or
   *  "Installing WordPress…" — sourced from lib/provisioning-step.ts. Replaces the
   *  cosmetic time-based cycling text in the provisioning view when present; null
   *  falls back to that cosmetic text (no real signal available yet). */
  liveStep?: string | null;
  /** True while a real, product-specific step is still in progress even though
   *  `transitional` (account/server status) has already gone false — e.g. Shared
   *  Hosting's account is ACTIVE but a just-ordered WordPress install is still
   *  running as a queued task. Only ever extends the provisioning view while this
   *  session was already watching (or just paid) — see the effect below — so a
   *  LATER, casual action (installing an app months on) never hijacks the screen. */
  liveStepActive?: boolean;
  /** Where "Go to your server" sends them — normally just this same page. */
  dashboardHref: string;
}) {
  const storageKey = `nxeon:overlay:${serverId}`;
  const [phase, setPhase] = useState<"hidden" | "provisioning" | "success">("hidden");
  const mountedAtRef = useRef<number | null>(null);
  // Real infra provisions in well under this — it's purely a perceived-progress
  // floor so the animation never flashes by unreadably fast (e.g. SANDBOX mode,
  // which completes instantly), not a claim about how long the real work takes.
  const MIN_PROVISIONING_MS = 3200;

  useEffect(() => {
    let watching = false;
    try {
      watching = sessionStorage.getItem(storageKey) === "watching";
    } catch {
      /* storage disabled — degrade to "never show" rather than guess */
    }

    if (transitional) {
      if (mountedAtRef.current == null) mountedAtRef.current = Date.now();
      setPhase("provisioning");
      try {
        sessionStorage.setItem(storageKey, "watching");
      } catch {
        /* ignore */
      }
      return;
    }

    // Not transitional anymore (by the base status alone). Before deciding this is
    // done, check for a real, product-specific follow-on step still running — e.g.
    // Shared Hosting's account just flipped ACTIVE but a WordPress install queued
    // at order time is still processing. Gated on watching/justPaid, same as the
    // block above: this must never resurrect the full-screen takeover for a LATER,
    // casual action (installing an app months after purchase) — only for a follow-
    // on step that belongs to the SAME order this session was already watching.
    if (liveStepActive && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
      setPhase("provisioning");
      return;
    }

/**
 * Real (not cosmetic) "what's actually happening right now" progress labels for
 * <ProvisioningOverlay/>, for both Shared Hosting and VPS/game-server orders.
 *
 * The provisioning workers (worker/hosting.ts, worker/index.ts) run in a SEPARATE
 * process from the web app (nxeon-worker.service vs nxeon-web.service), so an
 * in-memory signal (like lib/chat-bot-step.ts's TTL map, which works because the
 * chat bot and the poll route share one process) is not visible here — the signal
 * has to be durable. `HostingAccount.provisioningStep` / `Server.provisioningStep`
 * are those durable, best-effort columns: the worker writes a short human label
 * between real, observable command groups, and this module reads it back. A null
 * step means "no real signal yet" — callers fall back to generic/cosmetic text
 * rather than claiming false precision.
 *
 * For Shared Hosting specifically, "real progress" continues past the account
 * going ACTIVE: a one-click app install (WordPress, etc.) queued at order time
 * runs as a `HostingTask` AFTER the account is active, and that queue already has
 * genuine DB-persisted status transitions (PENDING → RUNNING → DONE/FAILED) — no
 * new instrumentation needed there, just a kind → label mapping.
 */

import { db } from "./db";

const HOSTING_TASK_LABELS: Record<string, string> = {
  WORDPRESS_INSTALL: "Installing WordPress…",
  APP_INSTALL: "Installing your application…",
  PHP_SWITCH: "Switching PHP version…",
  BACKUP: "Creating a backup…",
  RESTORE: "Restoring your backup…",
  CREATE_SUBDOMAIN: "Setting up your subdomain…",
  DELETE_SUBDOMAIN: "Removing your subdomain…",
  CREATE_ADDON_DOMAIN: "Connecting your domain…",
  DELETE_ADDON_DOMAIN: "Removing your domain…",
  CREATE_CRON: "Scheduling your cron job…",
  DELETE_CRON: "Removing your cron job…",
  INSTALL_DBTOOL: "Installing the database manager…",
  ENSURE_DBMGR: "Preparing your database manager…",
  APPLY_PLAN_LIMITS: "Applying your new plan…",
  RESET_DB_PASSWORD: "Resetting your database password…",
  SET_PRIMARY_DOMAIN: "Switching your primary domain…",
};

/**
 * The real step label for a Shared Hosting account, or null if there's nothing
 * genuine to say right now.
 *
 *  - PENDING/PROVISIONING: the account's own `provisioningStep` column, or a
 *    generic fallback if the worker hasn't written one yet (e.g. SANDBOX mode,
 *    which completes before any step is ever recorded).
 *  - ACTIVE: the label for whichever content task (WordPress/app install, PHP
 *    switch, …) is PENDING or RUNNING for this account, if any. This is what
 *    lets <ProvisioningOverlay/> keep showing progress through a post-order
 *    WordPress install even though the account itself is already ACTIVE.
 *  - Anything else (SUSPENDED/FAILED/DELETING, or ACTIVE with no live task):
 *    null.
 */
export async function hostingProvisioningStep(accountId: string): Promise<string | null> {
  const account = await db.hostingAccount.findUnique({
    where: { id: accountId },
    select: { status: true, provisioningStep: true },
  });
  if (!account) return null;
  if (account.status === "PENDING" || account.status === "PROVISIONING") {
    return account.provisioningStep || "Setting up your hosting account…";
  }
  if (account.status === "ACTIVE") {
    const task = await db.hostingTask.findFirst({
      where: { accountId, status: { in: ["PENDING", "RUNNING"] } },
      orderBy: { createdAt: "asc" },
      select: { kind: true },
    });
    if (task) return HOSTING_TASK_LABELS[task.kind] ?? "Finishing setup…";
  }
  return null;
}

/**
 * The real step label for a VPS/game-server order, or null. Only meaningful while
 * PENDING/PROVISIONING/REINSTALLING — worker/index.ts's provision() writes
 * `Server.provisioningStep` between its real, observable checkpoints (clone,
 * configure, start, guest-agent boot, SSH reachable, and — for game orders only —
 * the game's own port opening). A null return (no column value yet) means the
 * job hasn't reached its first checkpoint, or this deployment predates the
 * column; callers fall back to the existing cosmetic cycling text rather than
 * inventing a label for a phase we can't actually observe.
 */
export async function serverProvisioningStep(serverId: string): Promise<string | null> {
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { status: true, provisioningStep: true },
  });
  if (!server) return null;
  if (!["PENDING", "PROVISIONING", "REINSTALLING"].includes(server.status)) return null;
  return server.provisioningStep || null;
}
