546	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
547	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
548	  // token table. A rapid resubmit or a network retry with the same key can't create
549	  // a second account or take a second debit.
550	  const sessionKey = `hostorder:${key}`;
551	  try {
552	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
553	  } catch (e) {
554	    if (isUniqueViolation(e)) {
555	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
556	      // A completed prior attempt: replay its result (no second charge).
557	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
558	      // A failed prior attempt: clear it so an explicit retry can proceed.
559	      if (prior?.status === "FAILED") {
560	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
561	      } else {
562	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
563	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
564	      }
565	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
566	      try {
567	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
568	      } catch {
569	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
570	      }
571	    } else {
572	      throw e;
573	    }
574	  }
