576	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
577	  // the free temporary subdomain. All money movement, the first-month-free atomic
578	  // claim and the hostname claim happen inside orderHostingAccountFor's transaction.
579	  const res = await orderHostingAccountFor(user, input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB, partnerSource);
