581	    await db.fulfilledSession
582	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
583	      .catch(() => {});
584	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
585	  }
586	  await db.fulfilledSession
587	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
588	    .catch(() => {});
