export async function renameServer(
  serverId: string,
  label: string
): Promise<{ error?: string; label?: string | null }> {
  const { user } = await ownedServer(serverId);

  // Strip ASCII control characters, collapse whitespace, then trim.
  const clean = (label ?? "")
    .replace(/[\x00-\x1f\x7f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (clean.length > 40) return { error: "Name must be 40 characters or fewer." };
  const value = clean.length === 0 ? null : clean;

  await db.server.update({ where: { id: serverId }, data: { label: value } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.rename",
      detail: `${serverId} -> ${value ?? "(cleared)"}`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { label: value };
}

export async function saveGameConfig(
  serverId: string,
  variant: string,
  values: Record<string, unknown>
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);

  const family = familyFor(server);
  const schema = schemaFor(family);
  if (!family || !schema) {
    return { error: "This server doesn't support game settings." };
  }

  if (!isValidVariant(family, variant)) {
    return { error: "Pick a valid server type for this game." };
  }

  const validated = validateConfig(family, values);
  if (!validated.ok) return { error: validated.error };

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.server.update({
    where: { id: server.id },
    data: { gameVariant: variant, gameConfig: validated.values as any },
  });
  await db.job.create({ data: { type: "GAME_CONFIG", serverId: server.id } });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.config",
      detail: `${serverId} family=${family} variant=${variant}`,
    },
  });

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}
