export async function resizeServer(
  serverId: string,
  planId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: an upgrade debits the wallet (and can open a Stripe Checkout in
  // the customer's name), so it carries the same impersonation guard as every
  // other money movement — lib/actions-disk.ts expandServerDisk, lib/actions.ts
  // payAndDeploy/topUp/renewNow, and the domain transfer actions.
  // This one was missed, which made "upgrade the plan" the one charge an admin
  // impersonating a customer could still put on that customer's balance.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
  // stopping a customer from spending LESS would be a gate with no one to
  // protect. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Validate + price the upgrade (ownership already checked above). resizeQuote
  // recomputes the exact prorated charge over the remaining term.
  let quote;
  try {
    quote = await resizeQuote(serverId, planId);
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    throw e;
  }
  const { newPlan, prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
  // the same split (lib/wallet-split.ts) so displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  // Card portion > 0 → charge ONLY the remainder on the card (not the full
  // proration). The confirm route credits the card amount to the wallet and then
  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
  // share and the card the rest — wallet never touched before the card clears.
  if (cardCents > 0) {
    const checkout = await createResizeCheckout(user, cardCents, {
      serverId,
      planId,
      planName: newPlan.name,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
  // servers) → apply instantly, debiting the full proration from the wallet.
  try {
    await applyResize({ serverId, planId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

